solution:
function FindMin(nums: int[]) -> int {
  let lo = 0;
  let hi = nums.length() - 1;
  while (lo < hi) {
    let mid = (lo + hi) / 2;
    if (nums[mid] > nums[hi]) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return nums[lo];
}
